  );
}

"""Provider registry with dynamic registration, override management, and cost tracking."""

from __future__ import annotations

import logging
from dataclasses import dataclass, field
from datetime import datetime, timezone
from typing import TYPE_CHECKING, Any

if TYPE_CHECKING:
    from backend.providers.secrets import KeyVault

from backend.config import get_settings
from backend.providers.base import CostEvent, LLMProvider

logger = logging.getLogger(__name__)


class ProviderRegistry:
    """Mutable provider registry with override tracking and health checking.

    Inspired by Paperclip's mutable adapter registry with override pause/resume.
    Built-in providers are registered at init. External providers can be
    added, removed, or overridden at runtime without restart.
    """

    def __init__(self) -> None:
        self._providers: dict[str, type[LLMProvider]] = {}
        self._overrides: dict[str, type[LLMProvider]] = {}
        self._builtin_fallbacks: dict[str, type[LLMProvider]] = {}
        self._paused_overrides: set[str] = set()
        self._cost_tracker: CostTracker | None = None
        self._auto_register_builtins()

    def _auto_register_builtins(self) -> None:
        _BUILTIN_IMPORTS = [
            ("openai", "backend.providers.openai_provider", "OpenAIProvider"),
            ("anthropic", "backend.providers.anthropic_provider", "AnthropicProvider"),
            ("gemini", "backend.providers.gemini_provider", "GeminiProvider"),
            ("ollama", "backend.providers.ollama_provider", "OllamaProvider"),
            ("litellm", "backend.providers.litellm_provider", "LiteLLMProvider"),
        ]
        for name, module_path, cls_name in _BUILTIN_IMPORTS:
            try:
                import importlib
                mod = importlib.import_module(module_path)
                self._providers[name] = getattr(mod, cls_name)
            except ImportError:
                logger.debug("Skipping provider '%s': dependency not installed", name)

    def register(self, name: str, cls: type[LLMProvider]) -> None:
        self._providers[name] = cls
        logger.info("Registered provider: %s", name)

    def unregister(self, name: str) -> bool:
        if name in self._providers:
            del self._providers[name]
            self._overrides.pop(name, None)
            self._builtin_fallbacks.pop(name, None)
            self._paused_overrides.discard(name)
            logger.info("Unregistered provider: %s", name)
            return True
        return False

    def override(self, name: str, cls: type[LLMProvider]) -> None:
        """Override a provider with a custom implementation. Original is kept as fallback."""
        if name in self._providers:
            self._builtin_fallbacks[name] = self._providers[name]
        self._overrides[name] = cls
        self._providers[name] = cls
        logger.info("Overrode provider: %s", name)

    def set_override_paused(self, name: str, paused: bool) -> None:
        """Pause/resume an override, falling back to the builtin."""
        if paused and name in self._overrides and name in self._builtin_fallbacks:
            self._providers[name] = self._builtin_fallbacks[name]
            self._paused_overrides.add(name)
            logger.info("Paused override for provider: %s", name)
        elif not paused and name in self._paused_overrides and name in self._overrides:
            self._providers[name] = self._overrides[name]
            self._paused_overrides.discard(name)
            logger.info("Resumed override for provider: %s", name)

    def get(self, name: str) -> type[LLMProvider] | None:
        return self._providers.get(name)

    def list_providers(self) -> list[str]:
        return list(self._providers.keys())

    def set_cost_tracker(self, tracker: CostTracker) -> None:
        self._cost_tracker = tracker

    @property
    def cost_tracker(self) -> CostTracker | None:
        return self._cost_tracker

    def create(self, name: str | None = None, settings: Any = None) -> LLMProvider:
        """Create a configured provider instance.

        If name is None, uses settings.default_provider.
        If the provider name is unknown, falls back to LiteLLM when enabled.
        """
        settings = settings or get_settings()
        name = name or settings.default_provider

        self._validate_api_key(name, settings)

        if name not in self._providers:
            if getattr(settings, "litellm_fallback_enabled", False):
                from backend.providers.litellm_provider import LiteLLMProvider

                logger.info("Unknown provider '%s' — routing through LiteLLM", name)
                return LiteLLMProvider(model=name, api_key=settings.openai_api_key)
            raise ValueError(
                f"Unknown provider: {name}. Available: {self.list_providers()}"
            )

        cls = self._providers[name]
        provider = self._construct_provider(cls, name, settings)

        if self._cost_tracker:
            provider.set_cost_callback(self._cost_tracker.record)

        if getattr(settings, "caching_enabled", False):
            provider = _wrap_cached(provider, name, settings)

        if getattr(settings, "resilience_enabled", False):
            provider = _wrap_resilient(provider, name, settings)

        return provider

    def _construct_provider(
        self, cls: type[LLMProvider], name: str, settings: Any
    ) -> LLMProvider:
        """Generic provider constructor. Routes by name to pass the right settings."""
        if name == "openai":
            return cls(
                api_key=settings.openai_api_key,
                model=settings.openai_model,
                embedding_model=settings.embedding_model,
            )
        elif name == "anthropic":
            return cls(
                api_key=settings.anthropic_api_key,
                model=settings.anthropic_model,
                embedding_model=settings.embedding_model,
                base_url=settings.anthropic_base_url,
            )
        elif name == "gemini":
            return cls(
                api_key=settings.gemini_api_key,
                model=settings.gemini_model,
            )
        elif name == "ollama":
            return cls(
                base_url=settings.ollama_base_url,
                model=settings.ollama_model,
            )
        elif name == "litellm":
            return cls(
                model=settings.litellm_model,
                api_key=settings.openai_api_key,
            )
        else:
            return cls()

    @staticmethod
    def _validate_api_key(provider_name: str, settings: Any) -> None:
        _KEY_MAP = {
            "openai": ("openai_api_key", "EROCK_OPENAI_API_KEY"),
            "anthropic": ("anthropic_api_key", "EROCK_ANTHROPIC_API_KEY"),
            "gemini": ("gemini_api_key", "EROCK_GEMINI_API_KEY"),
            "litellm": ("openai_api_key", "EROCK_OPENAI_API_KEY"),
        }
        if provider_name not in _KEY_MAP:
            return
        attr_name, env_var = _KEY_MAP[provider_name]
        value = getattr(settings, attr_name, None)
        if not value or not value.strip():
            raise SystemExit(
                f"{env_var} not set. "
                f"Add it to .env or set the environment variable:\n"
                f"  export {env_var}=sk-...\n"
                f"Or switch to a provider that doesn't require a key: ollama"
            )


# Module-level singleton
_registry: ProviderRegistry | None = None


def _get_registry() -> ProviderRegistry:
    global _registry
    if _registry is None:
        _registry = ProviderRegistry()
    return _registry


def get_registry() -> ProviderRegistry:
    """Get the global provider registry."""
    return _get_registry()


def register_provider(name: str, cls: type[LLMProvider]) -> None:
    """Register a custom provider. Backward-compatible entry point."""
    _get_registry().register(name, cls)


def create_provider(name: str | None = None) -> LLMProvider:
    """Create a configured provider. Drop-in replacement for the old factory."""
    return _get_registry().create(name)


def _validate_api_key(provider_name: str, settings: Any) -> None:
    """Backward-compatible module-level alias."""
    ProviderRegistry._validate_api_key(provider_name, settings)


# ---- Resilience Wiring ----

_vault: KeyVault | None = None


def _get_vault(settings: Any) -> KeyVault | None:
    global _vault
    if _vault is not None:
        return _vault
    if not getattr(settings, "secrets_master_password", None):
        return None
    from backend.providers.secrets import KeyVault

    _vault = KeyVault(
        master_password=settings.secrets_master_password,
        persist_path=f"{settings.secrets_persist_dir}/vault.json",
    )
    try:
        _vault.load()
    except Exception:
        logger.warning("Failed to load key vault — starting fresh")
    return _vault


def _wrap_cached(
    provider: LLMProvider, name: str, settings: Any
) -> LLMProvider:
    from backend.providers.cache import CachedProvider, InMemoryCache, SemanticCache

    cache_type = getattr(settings, "caching_type", "memory")
    max_size = getattr(settings, "caching_max_size", 1000)
    ttl_seconds = getattr(settings, "caching_ttl_seconds", 3600)

    if cache_type == "semantic":
        from backend.pipeline.knowledge.embedding_providers import create_embedding_provider
        from backend.pipeline.knowledge.embedding_service import EmbeddingService

        emb_provider = create_embedding_provider(
            provider_name=getattr(settings, "embedding_provider", "openai"),
            model=getattr(settings, "embedding_model", "text-embedding-3-small"),
            api_key=getattr(settings, "openai_api_key", ""),
            base_url=getattr(settings, "ollama_base_url", "http://localhost:11434"),
            dimension=getattr(settings, "embedding_dimension", 1536) or None,
        )
        emb_service = EmbeddingService(
            emb_provider,
            batch_size=getattr(settings, "embedding_batch_size", 100),
        )
        semantic_cache = SemanticCache(
            embedding_service=emb_service,
            persist_dir=getattr(settings, "caching_persist_dir", "./data/chroma"),
            similarity_threshold=getattr(settings, "caching_similarity_threshold", 0.95),
            ttl_seconds=ttl_seconds,
            max_size=max_size,
        )
        memory_cache = InMemoryCache(max_size=max_size, ttl_seconds=ttl_seconds)
        return CachedProvider(
            wrapped=provider,
            cache=memory_cache,
            cache_type="semantic",
            semantic_cache=semantic_cache,
        )

    memory_cache = InMemoryCache(max_size=max_size, ttl_seconds=ttl_seconds)
    return CachedProvider(wrapped=provider, cache=memory_cache, cache_type="memory")


def _wrap_resilient(
    provider: LLMProvider, name: str, settings: Any
) -> LLMProvider:
    from backend.providers.resilience import CircuitBreaker, ResilientProvider, RetryConfig
    from backend.providers.resilience.circuit_breaker import _breakers

    breaker = _breakers.setdefault(
        name,
        CircuitBreaker(
            failure_threshold=settings.circuit_breaker_failure_threshold,
            reset_timeout=settings.circuit_breaker_reset_timeout,
            cooldown_percent=getattr(settings, "circuit_breaker_cooldown_percent", 0.1),
        ),
    )
    retry_config = RetryConfig(
        max_retries=settings.retry_max_retries,
        base_delay=settings.retry_base_delay,
        max_delay=settings.retry_max_delay,
        cooldown_delay=settings.retry_cooldown_delay,
    )
    vault = _get_vault(settings)
    return ResilientProvider(provider, breaker, retry_config, vault)


# ---- Cost Tracking ----

class CostTracker:
    """Per-provider cost tracking with multi-dimensional aggregation.

    Inspired by Paperclip's cost tracking with 6 aggregation dimensions.
    """

    # Rough per-1K-token costs (USD). Can be overridden per provider/model.
    DEFAULT_COSTS: dict[str, dict[str, float]] = {
        "openai": {"input": 0.0025, "output": 0.01},
        "anthropic": {"input": 0.003, "output": 0.015},
        "gemini": {"input": 0.00125, "output": 0.005},
        "ollama": {"input": 0.0, "output": 0.0},
        "litellm": {"input": 0.0025, "output": 0.01},
    }

    def __init__(self) -> None:
        self._events: list[CostEvent] = []
        self._cost_overrides: dict[str, dict[str, float]] = {}

    def set_cost_per_1k(self, provider: str, input_cost: float, output_cost: float) -> None:
        self._cost_overrides[provider] = {"input": input_cost, "output": output_cost}

    def record(self, event: CostEvent) -> None:
        if event.cost_usd == 0.0:
            rates = self._cost_overrides.get(event.provider, self.DEFAULT_COSTS.get(event.provider, {"input": 0.0, "output": 0.0}))
            event.cost_usd = (
                (event.input_tokens / 1000.0) * rates.get("input", 0.0)
                + (event.output_tokens / 1000.0) * rates.get("output", 0.0)
            )
        self._events.append(event)

    def summary(self) -> dict[str, Any]:
        if not self._events:
            return {"total_cost_usd": 0.0, "total_tokens": 0, "event_count": 0}
        return {
            "total_cost_usd": sum(e.cost_usd for e in self._events),
            "total_tokens": sum(e.total_tokens for e in self._events),
            "total_input_tokens": sum(e.input_tokens for e in self._events),
            "total_output_tokens": sum(e.output_tokens for e in self._events),
            "event_count": len(self._events),
        }

    def by_provider(self) -> dict[str, dict[str, Any]]:
        result: dict[str, dict[str, Any]] = {}
        for e in self._events:
            if e.provider not in result:
                result[e.provider] = {"cost_usd": 0.0, "input_tokens": 0, "output_tokens": 0, "calls": 0}
            r = result[e.provider]
            r["cost_usd"] += e.cost_usd
            r["input_tokens"] += e.input_tokens
            r["output_tokens"] += e.output_tokens
            r["calls"] += 1
        return result

    def by_stage(self) -> dict[str, dict[str, Any]]:
        result: dict[str, dict[str, Any]] = {}
        for e in self._events:
            stage = e.stage or "unspecified"
            if stage not in result:
                result[stage] = {"cost_usd": 0.0, "input_tokens": 0, "output_tokens": 0, "calls": 0}
            r = result[stage]
            r["cost_usd"] += e.cost_usd
            r["input_tokens"] += e.input_tokens
            r["output_tokens"] += e.output_tokens
            r["calls"] += 1
        return result

    def by_model(self) -> dict[str, dict[str, Any]]:
        result: dict[str, dict[str, Any]] = {}
        for e in self._events:
            key = f"{e.provider}/{e.model}"
            if key not in result:
                result[key] = {"cost_usd": 0.0, "input_tokens": 0, "output_tokens": 0, "calls": 0}
            r = result[key]
            r["cost_usd"] += e.cost_usd
            r["input_tokens"] += e.input_tokens
            r["output_tokens"] += e.output_tokens
            r["calls"] += 1
        return result

    def reset(self) -> None:
        self._events.clear()

    def events_in_range(self, start: float, end: float) -> list:
        """Return cost events whose timestamp falls within [start, end] epoch seconds."""
        return [
            e for e in self._events
            if start <= e.timestamp.timestamp() <= end
        ]

    def persist(self, path: str) -> None:
        """Write all cost events to a JSONL file."""
        from pathlib import Path
        Path(path).parent.mkdir(parents=True, exist_ok=True)
        with open(path, "w", encoding="utf-8") as f:
            for e in self._events:
                line = json.dumps({
                    "provider": e.provider,
                    "model": e.model,
                    "input_tokens": e.input_tokens,
                    "output_tokens": e.output_tokens,
                    "cost_usd": e.cost_usd,
                    "stage": e.stage,
                    "run_id": e.run_id,
                    "timestamp": e.timestamp.isoformat(),
                })
                f.write(line + "\n")

    @classmethod
    def load(cls, path: str) -> "CostTracker":
        """Load cost events from a JSONL file."""
        tracker = cls()
        from backend.providers.base import CostEvent
        from datetime import datetime, timezone
        with open(path, encoding="utf-8") as f:
            for line in f:
                data = json.loads(line.strip())
                event = CostEvent(
                    provider=data["provider"],
                    model=data["model"],
                    input_tokens=data["input_tokens"],
                    output_tokens=data["output_tokens"],
                    cost_usd=data.get("cost_usd", 0.0),
                    stage=data.get("stage", ""),
                    run_id=data.get("run_id"),
                    timestamp=datetime.fromisoformat(data.get("timestamp", datetime.now(timezone.utc).isoformat())),
                )
                tracker._events.append(event)
        return tracker

"""Entity-centric knowledge graph with Hebbian-like edge consolidation.

Stores entities (papers, authors, methods, datasets, concepts) and their
relationships (cites, uses_method, extends, contradicts, etc.) in an
in-memory graph with JSON persistence. Optional changeset versioning
and adjacency indexing for O(1) neighbor lookup.
"""

from __future__ import annotations

import json
import logging
from pathlib import Path
from typing import TYPE_CHECKING

from backend.pipeline.knowledge.entities import EntityResolution, EntityType, KnowledgeEntity
from backend.pipeline.knowledge.relationships import KnowledgeRelationship, RelationType
from backend.pipeline.knowledge.truth import TruthValue

if TYPE_CHECKING:
    from backend.pipeline.knowledge.activation import ActivationPipeline
    from backend.pipeline.knowledge.adjacency import AdjacencyIndex
    from backend.pipeline.knowledge.streams import StreamRegistry
    from backend.pipeline.knowledge.versioning import ChangeBuffer, VersionLog

logger = logging.getLogger(__name__)


class KnowledgeGraph:
    """Entity-centric knowledge graph with Hebbian-like edge consolidation."""

    def __init__(
        self, persist_path: str = "./data/knowledge_graph.json", versioning_enabled: bool = False
    ):
        self._path = Path(persist_path)
        self._entities: dict[str, KnowledgeEntity] = {}
        self._relationships: list[KnowledgeRelationship] = []
        self._resolution = EntityResolution()
        self._hash_index: dict[str, str] = {}
        self._incoming_set: dict[str, set[str]] = {}
        self._versioning_enabled = versioning_enabled
        self._change_buffer: ChangeBuffer | None = None
        self._version_log: VersionLog | None = None
        self._adjacency: AdjacencyIndex | None = None
        self._stream_registry: StreamRegistry | None = None
        if versioning_enabled:
            from backend.pipeline.knowledge.adjacency import AdjacencyIndex
            from backend.pipeline.knowledge.versioning import ChangeBuffer, VersionLog

            changes_path = str(persist_path).replace(".json", ".changes.jsonl")
            self._change_buffer = ChangeBuffer()
            self._version_log = VersionLog(changes_path)
            self._adjacency = AdjacencyIndex()
        self._load()

    def add_entity(self, entity: KnowledgeEntity) -> str:
        """Add an entity. Returns canonical ID. Deduplicates by content hash when IDs match."""
        canonical = self._resolution.canonical_id(entity.id)
        content_hash = entity.content_hash

        if canonical in self._entities:
            existing = self._entities[canonical]
            if self._change_buffer:
                from backend.pipeline.knowledge.versioning import ChangeRecord

                old_hash = ChangeRecord.compute_content_hash(existing.model_dump(mode="json"))
            existing.truth = existing.truth.revise(entity.truth)
            if self._change_buffer:
                new_hash = ChangeRecord.compute_content_hash(existing.model_dump(mode="json"))
                self._change_buffer.record_truth_update(canonical, old_hash, new_hash)
            self._hash_index[content_hash] = canonical
            return canonical

        # Content-hash dedup: same content, same ID path — revise truth
        if content_hash in self._hash_index:
            existing_id = self._hash_index[content_hash]
            if existing_id == canonical:
                existing = self._entities.get(existing_id)  # type: ignore[assignment]
                if existing:
                    if self._change_buffer:
                        from backend.pipeline.knowledge.versioning import ChangeRecord

                        old_hash = ChangeRecord.compute_content_hash(
                            existing.model_dump(mode="json")
                        )
                    existing.truth = existing.truth.revise(entity.truth)
                    if self._change_buffer:
                        new_hash = ChangeRecord.compute_content_hash(
                            existing.model_dump(mode="json")
                        )
                        self._change_buffer.record_truth_update(existing_id, old_hash, new_hash)
                    return existing_id

        self._entities[canonical] = entity
        self._hash_index[content_hash] = canonical
        if self._change_buffer:
            from backend.pipeline.knowledge.versioning import ChangeRecord

            ch = ChangeRecord.compute_content_hash(entity.model_dump(mode="json"))
            self._change_buffer.record_entity_add(canonical, ch)
        return canonical

    def add_relationship(self, rel: KnowledgeRelationship) -> None:
        """Add a relationship. If similar one exists, reinforce weight."""
        source = self._resolution.canonical_id(rel.source_id)
        target = self._resolution.canonical_id(rel.target_id)

        for existing in self._relationships:
            if (
                self._resolution.canonical_id(existing.source_id) == source
                and self._resolution.canonical_id(existing.target_id) == target
                and existing.relation_type == rel.relation_type
            ):
                self.reinforce(source, target, rel.relation_type, delta=0.1)
                existing.truth = existing.truth.revise(rel.truth)
                return

        self._relationships.append(
            KnowledgeRelationship(
                source_id=source,
                target_id=target,
                relation_type=rel.relation_type,
                weight=rel.weight,
                evidence=rel.evidence,
                truth=rel.truth,
            )
        )
        self._incoming_set.setdefault(target, set()).add(source)
        if self._adjacency:
            self._adjacency.add_relationship(source, target)
        if self._change_buffer:
            from backend.pipeline.knowledge.versioning import ChangeRecord

            content_hash = ChangeRecord.compute_content_hash(rel.model_dump(mode="json"))
            self._change_buffer.record_relationship_add(source, target, content_hash)

        # Truth-value revision when CONTRADICTS relation is added
        if rel.relation_type == RelationType.CONTRADICTS:
            src_entity = self._entities.get(source)
            tgt_entity = self._entities.get(target)
            for entity in (src_entity, tgt_entity):
                if entity and hasattr(entity, 'truth') and entity.truth:
                    entity.truth = TruthValue(
                        frequency=entity.truth.frequency,
                        confidence=entity.truth.confidence * 0.8,
                        evidence_count=entity.truth.evidence_count,
                    )

    def get_entity(self, entity_id: str) -> KnowledgeEntity | None:
        """Get an entity by ID (resolves to canonical)."""
        canonical = self._resolution.canonical_id(entity_id)
        return self._entities.get(canonical)

    def get_by_content_hash(self, content_hash: str) -> KnowledgeEntity | None:
        """Get an entity by its content hash (O(1) reverse lookup)."""
        entity_id = self._hash_index.get(content_hash)
        if entity_id:
            return self._entities.get(entity_id)
        return None

    def get_referencing_relationships(self, entity_id: str) -> list[KnowledgeRelationship]:
        """Get all relationships that reference this entity (incoming + outgoing)."""
        canonical = self._resolution.canonical_id(entity_id)
        return [
            r
            for r in self._relationships
            if self._resolution.canonical_id(r.source_id) == canonical
            or self._resolution.canonical_id(r.target_id) == canonical
        ]

    def get_outgoing_relationships(self, entity_id: str) -> list[KnowledgeRelationship]:
        canonical = self._resolution.canonical_id(entity_id)
        return [
            r for r in self._relationships
            if self._resolution.canonical_id(r.source_id) == canonical
        ]

    def get_incoming_relationships(self, entity_id: str) -> list[KnowledgeRelationship]:
        canonical = self._resolution.canonical_id(entity_id)
        return [
            r for r in self._relationships
            if self._resolution.canonical_id(r.target_id) == canonical
        ]

    @property
    def entity_count(self) -> int:
        return len(self._entities)

    def get_neighbors(
        self,
        entity_id: str,
        relation_type: RelationType | None = None,
    ) -> list[KnowledgeEntity]:
        """Get neighboring entities connected by relationships."""
        canonical = self._resolution.canonical_id(entity_id)

        if self._adjacency and relation_type is None:
            neighbor_ids = self._adjacency.get_neighbor_ids(canonical)
            return [self._entities[nid] for nid in neighbor_ids if nid in self._entities]

        # Linear scan fallback (used when filtering by relation_type or no adjacency index)
        found_neighbors: set[str] = set()
        for rel in self._relationships:
            src = self._resolution.canonical_id(rel.source_id)
            tgt = self._resolution.canonical_id(rel.target_id)
            if relation_type and rel.relation_type != relation_type:
                continue
            if src == canonical:
                found_neighbors.add(tgt)
            elif tgt == canonical:
                found_neighbors.add(src)

        return [self._entities[nid] for nid in found_neighbors if nid in self._entities]

    def reinforce(
        self,
        source_id: str,
        target_id: str,
        relation_type: RelationType,
        delta: float = 0.1,
    ) -> None:
        """Increase edge weight (Hebbian-like reinforcement)."""
        source = self._resolution.canonical_id(source_id)
        target = self._resolution.canonical_id(target_id)

        for rel in self._relationships:
            if (
                self._resolution.canonical_id(rel.source_id) == source
                and self._resolution.canonical_id(rel.target_id) == target
                and rel.relation_type == relation_type
            ):
                old_weight = rel.weight
                rel.weight = min(2.0, rel.weight + delta)
                if self._change_buffer:
                    self._change_buffer.record_reinforce(source, target, old_weight, rel.weight)
                return

    def weaken(
        self,
        source_id: str,
        target_id: str,
        relation_type: RelationType,
        delta: float = 0.05,
    ) -> None:
        """Decrease edge weight (Hebbian-like weakening)."""
        source = self._resolution.canonical_id(source_id)
        target = self._resolution.canonical_id(target_id)

        for rel in self._relationships:
            if (
                self._resolution.canonical_id(rel.source_id) == source
                and self._resolution.canonical_id(rel.target_id) == target
                and rel.relation_type == relation_type
            ):
                old_weight = rel.weight
                rel.weight = max(0.0, rel.weight - delta)
                if self._change_buffer:
                    self._change_buffer.record_weaken(source, target, old_weight, rel.weight)
                return

    def merge_entities(self, id_a: str, id_b: str) -> None:
        """Merge two entities (e.g., duplicate author names)."""
        self._resolution.union(id_a, id_b)
        canonical = self._resolution.canonical_id(id_a)
        other = id_b if canonical == id_a else id_a

        if other in self._entities and canonical not in self._entities:
            entity = self._entities.pop(other)
            entity.id = canonical
            self._entities[canonical] = entity

        if self._change_buffer:
            self._change_buffer.record_merge(canonical, other)
        if self._adjacency:
            self._adjacency.remove_entity(other)

    def get_graph_stats(self) -> dict:
        """Return graph statistics."""
        return {
            "entity_count": len(self._entities),
            "relationship_count": len(self._relationships),
            "entity_types": {
                et.value: sum(1 for e in self._entities.values() if e.entity_type == et)
                for et in EntityType
            },
            "relation_types": {
                rt.value: sum(1 for r in self._relationships if r.relation_type == rt)
                for rt in RelationType
            },
        }

    def _load(self) -> None:
        if not self._path.exists():
            return
        try:
            data = json.loads(self._path.read_text())
            for ed in data.get("entities", []):
                entity = KnowledgeEntity(**ed)
                self._entities[entity.id] = entity
                self._hash_index[entity.content_hash] = entity.id
                self._resolution.find(entity.id)
            for rd in data.get("relationships", []):
                self._relationships.append(KnowledgeRelationship(**rd))
            if self._adjacency:
                edges = [(r.source_id, r.target_id) for r in self._relationships]
                self._adjacency.rebuild(edges)
            logger.info(
                "Loaded knowledge graph: %d entities, %d relationships",
                len(self._entities),
                len(self._relationships),
            )
        except Exception as e:
            logger.warning("Failed to load knowledge graph: %s", e)

    def save(self) -> None:
        """Persist the knowledge graph to disk."""
        self._path.parent.mkdir(parents=True, exist_ok=True)
        if self._change_buffer and self._version_log:
            records = self._change_buffer.flush()
            self._version_log.append(records)
            if self._stream_registry:
                self._stream_registry.process_changes(records)
        data = {
            "entities": [e.model_dump(mode="json") for e in self._entities.values()],
            "relationships": [r.model_dump(mode="json") for r in self._relationships],
        }
        self._path.write_text(json.dumps(data, indent=2, default=str))

    def get_version_log(self) -> VersionLog | None:
        return self._version_log

    def get_changes_since(self, version: int):
        if self._version_log:
            return self._version_log.get_changes_since(version)
        return []

    def attach_stream_registry(self, registry: StreamRegistry) -> None:
        self._stream_registry = registry

    def compute_activation(self, entity_id: str, pipeline: ActivationPipeline) -> float:
        entity = self.get_entity(entity_id)
        if not entity:
            return 0.0
        from backend.pipeline.knowledge.activation import ActivationContext

        context = ActivationContext(
            entity_id=entity_id,
            current_truth=entity.truth,
        )
        return pipeline.compute(context)

    def rank_entities_by_activation(
        self, entity_type: EntityType | None, pipeline: ActivationPipeline
    ) -> list[tuple[str, float]]:
        results = []
        for eid, entity in self._entities.items():
            if entity_type and entity.entity_type != entity_type:
                continue
            score = self.compute_activation(eid, pipeline)
            results.append((eid, score))
        return sorted(results, key=lambda x: x[1], reverse=True)

