"""Pipeline DB persistence operations."""

import json
import logging
from pathlib import Path
from typing import Any

logger = logging.getLogger(__name__)

_CHECKPOINT_DIR = Path("./data/checkpoints")


class PipelinePersistence:
    """Handles all database writes for pipeline runs."""

    def __init__(self):
        self.warnings: list[str] = []

    def get_warnings(self) -> list[str]:
        return self.warnings.copy()

    def create_run_record(self, domain: str, params: dict) -> int | None:
        try:
            from backend.db import crud
            from backend.db.database import get_session

            with get_session() as session:
                db_run = crud.create_pipeline_run(
                    session,
                    domain=domain,
                    status="running",
                    current_stage="initializing",
                    config_json=json.dumps(params),
                )
                return db_run.id
        except Exception as e:
            logger.warning("Failed to create DB run record: %s", e)
            self.warnings.append(f"create_run_record: {e}")
            return None

    def persist_gaps(self, result, db_run_id: int | None) -> None:
        if not db_run_id or not result.gaps:
            return
        try:
            from backend.db import crud
            from backend.db.database import get_session

            with get_session() as session:
                for gap in result.gaps:
                    crud.create_gap(
                        session,
                        title=gap.title,
                        description=gap.description,
                        gap_type=gap.gap_type,
                        confidence=gap.confidence,
                        potential_impact=gap.potential_impact,
                        pipeline_run_id=db_run_id,
                    )
        except Exception as e:
            logger.warning("Failed to persist gaps: %s", e)
            self.warnings.append(f"persist_gaps: {e}")

    def persist_papers(self, papers: list, db_run_id: int | None) -> None:
        if not db_run_id:
            return
        try:
            from backend.db import crud
            from backend.db.database import get_session

            with get_session() as session:
                for paper in papers:
                    if not crud.get_paper_by_source_id(session, paper.id):
                        crud.create_paper(
                            session,
                            source_id=paper.id,
                            source=paper.source,
                            title=paper.title,
                            abstract=paper.abstract,
                            authors=json.dumps([a.name for a in paper.authors])
                            if paper.authors
                            else "[]",
                            year=paper.year,
                            venue=paper.venue,
                            citation_count=paper.citation_count,
                            url=paper.url,
                            doi=paper.doi,
                            arxiv_id=paper.arxiv_id,
                            keywords=json.dumps(paper.keywords) if paper.keywords else "[]",
                        )
        except Exception as e:
            logger.warning("Failed to persist papers: %s", e)
            self.warnings.append(f"persist_papers: {e}")

    def persist_ideas(self, result, db_run_id: int | None) -> None:
        if not db_run_id or not result.ideas:
            return
        try:
            from backend.db import crud
            from backend.db.database import get_session

            with get_session() as session:
                for i, idea in enumerate(result.ideas):
                    nov = result.novelty_reports.get(i)
                    feas = result.feasibility_reports.get(i)
                    db_idea = crud.create_idea(
                        session,
                        title=idea.title,
                        problem_statement=idea.problem_statement,
                        proposed_method=idea.proposed_method,
                        expected_contributions=idea.expected_contributions,
                        domain=idea.domain,
                        pipeline_run_id=db_run_id,
                    )
                    if nov or feas:
                        crud.update_idea_scores(
                            session,
                            db_idea.id,
                            novelty_score=nov.overall_score if nov else None,
                            feasibility_score=feas.overall_score if feas else None,
                            novelty_report=json.dumps(
                                {
                                    "method_novelty": nov.method_novelty,
                                    "problem_novelty": nov.problem_novelty,
                                    "domain_transfer": nov.domain_transfer,
                                    "combination_novelty": nov.combination_novelty,
                                    "novelty_arguments": nov.novelty_arguments,
                                }
                            )
                            if nov
                            else None,
                            feasibility_report=json.dumps(
                                {
                                    "data_availability": feas.data_availability,
                                    "computational_requirements": feas.computational_requirements,
                                    "methodological_complexity": feas.methodological_complexity,
                                    "evaluation_plan": feas.evaluation_plan,
                                    "reasoning": feas.reasoning,
                                    "estimated_timeline": feas.estimated_timeline,
                                }
                            )
                            if feas
                            else None,
                        )
        except Exception as e:
            logger.warning("Failed to persist ideas: %s", e)
            self.warnings.append(f"persist_ideas: {e}")

    def persist_proposals(self, result, db_run_id: int | None) -> None:
        if not db_run_id or not result.proposals:
            return
        try:
            from sqlalchemy import select

            from backend.db import crud
            from backend.db.database import get_session
            from backend.db.models import Idea

            with get_session() as session:
                for i, proposal in result.proposals.items():
                    idea = result.ideas[i] if i < len(result.ideas) else None
                    if idea:
                        db_idea_row = session.execute(
                            select(Idea).where(
                                Idea.title == idea.title,
                                Idea.pipeline_run_id == db_run_id,
                            )
                        ).scalar_one_or_none()
                        if db_idea_row:
                            sections_to_store = {
                                k: v for k, v in proposal.sections.items() if k != "validated_text"
                            }
                            crud.create_proposal(
                                session,
                                idea_id=db_idea_row.id,
                                content_md=proposal.to_markdown(),
                                references_json=json.dumps(proposal.sections.get("references", [])),
                                sections_json=json.dumps(sections_to_store),
                            )
        except Exception as e:
            logger.warning("Failed to persist proposals: %s", e)
            self.warnings.append(f"persist_proposals: {e}")

    def mark_run_failed(self, db_run_id: int | None, message: str) -> None:
        if not db_run_id:
            return
        try:
            from backend.db import crud
            from backend.db.database import get_session

            with get_session() as session:
                crud.update_pipeline_run(session, db_run_id, status="failed", error_message=message)
        except Exception as e:
            logger.warning("Failed to mark DB run as failed: %s", e)
            self.warnings.append(f"mark_run_failed: {e}")

    def mark_run_completed(self, db_run_id: int | None) -> None:
        if not db_run_id:
            return
        try:
            from backend.db import crud
            from backend.db.database import get_session

            with get_session() as session:
                crud.update_pipeline_run(session, db_run_id, status="completed")
        except Exception as e:
            logger.warning("Failed to mark DB run as completed: %s", e)
            self.warnings.append(f"mark_run_completed: {e}")

    # ── Checkpoint persistence (durable execution) ─────────────────

    def save_checkpoint(self, checkpoint: "RunCheckpoint") -> None:
        """Save a run checkpoint to disk."""
        try:
            _CHECKPOINT_DIR.mkdir(parents=True, exist_ok=True)
            path = _CHECKPOINT_DIR / f"{checkpoint.run_id}.json"
            path.write_text(checkpoint.to_json(), encoding="utf-8")
            logger.info("Checkpoint saved: %s", checkpoint.run_id)
        except Exception as e:
            logger.warning("Failed to save checkpoint: %s", e)
            self.warnings.append(f"save_checkpoint: {e}")

    def load_checkpoint(self, run_id: str) -> "RunCheckpoint | None":
        """Load a run checkpoint from disk."""
        try:
            path = _CHECKPOINT_DIR / f"{run_id}.json"
            if not path.exists():
                return None
            from backend.pipeline.execution.run_state import RunCheckpoint
            return RunCheckpoint.from_json(path.read_text(encoding="utf-8"))
        except Exception as e:
            logger.warning("Failed to load checkpoint for %s: %s", run_id, e)
            self.warnings.append(f"load_checkpoint: {e}")
            return None

    def list_checkpoints(self) -> list[dict]:
        """List all resumable checkpoints."""
        results = []
        if not _CHECKPOINT_DIR.exists():
            return results
        for path in _CHECKPOINT_DIR.glob("*.json"):
            try:
                from backend.pipeline.execution.run_state import RunCheckpoint
                cp = RunCheckpoint.from_json(path.read_text(encoding="utf-8"))
                results.append({
                    "run_id": cp.run_id,
                    "state": cp.state.value,
                    "completed_stages": sum(1 for s in cp.stages if s.status.value == "completed"),
                    "total_stages": len(cp.stages),
                })
            except Exception:
                pass
        return results

    # ---- State Reconstruction for Resume ----

    def get_run_by_uuid(self, run_id: str) -> Any | None:
        """Look up a PipelineRun by its UUID string."""
        from backend.db.crud import list_pipeline_runs
        with self._session() as session:
            runs = list_pipeline_runs(session, limit=100)
            for run in runs:
                if str(run.id) == run_id or run_id.endswith(str(run.id)):
                    return run
        return None

    def load_gaps(self, run_db_id: int) -> list:
        """Load ResearchGap objects from database for a pipeline run."""
        from backend.db.crud import get_pipeline_run
        with self._session() as session:
            run = get_pipeline_run(session, run_db_id)
            if not run:
                return []
            from backend.pipeline.gap_analysis.models import ResearchGap
            gaps = []
            for gap_db in getattr(run, "gaps", []):
                gaps.append(ResearchGap(
                    title=gap_db.title,
                    description=gap_db.description,
                    gap_type=gap_db.gap_type,
                    confidence=gap_db.confidence,
                    potential_impact=getattr(gap_db, "potential_impact", ""),
                ))
            return gaps

    def load_ideas(self, run_db_id: int) -> list:
        """Load ResearchIdea objects from database for a pipeline run."""
        from backend.db.crud import get_pipeline_run
        with self._session() as session:
            run = get_pipeline_run(session, run_db_id)
            if not run:
                return []
            from backend.pipeline.generation.models import ResearchIdea
            ideas = []
            for idea_db in getattr(run, "ideas", []):
                ideas.append(ResearchIdea(
                    title=idea_db.title,
                    problem_statement=getattr(idea_db, "problem_statement", ""),
                    proposed_method=getattr(idea_db, "proposed_method", ""),
                    domain=getattr(idea_db, "domain", "AI/NLP"),
                    score=getattr(idea_db, "overall_score", 0.0) or 0.0,
                ))
            return ideas

"""Proposal synthesis — generate structured research proposals."""

import logging
from pathlib import Path

from jinja2 import Template

from backend.pipeline.feasibility.feasibility_scorer import FeasibilityReport
from backend.pipeline.generation.models import ResearchIdea
from backend.pipeline.literature.models import Paper
from backend.pipeline.novelty.novelty_checker import NoveltyReport
from backend.providers.base import LLMProvider

logger = logging.getLogger(__name__)

PROMPT_DIR = Path(__file__).parent / "prompts"


class ResearchProposal:
    def __init__(self, idea_id: int | None = None, **sections):
        self.idea_id = idea_id
        self.sections = sections

    @property
    def title(self) -> str:
        return self.sections.get("title", "Untitled Proposal")

    @property
    def abstract(self) -> str:
        return self.sections.get("abstract", "")

    def to_markdown(self) -> str:
        """Convert proposal to Markdown format."""
        md_parts = []
        for key, value in self.sections.items():
            if key == "references":
                md_parts.append("## References\n")
                for i, ref in enumerate(value if isinstance(value, list) else [value], 1):
                    if isinstance(ref, dict):
                        authors = ref.get("authors", "Unknown")
                        year = ref.get("year", "n.d.")
                        title = ref.get("title", "Untitled")
                        venue = ref.get("venue", "")
                        doi = ref.get("doi", "")
                        url = ref.get("url", "")
                        line = f"[{i}] {authors} ({year}). {title}."
                        if venue:
                            line += f" {venue}."
                        if doi:
                            line += f" DOI: {doi}"
                        elif url:
                            line += f" URL: {url}"
                        md_parts.append(line)
                    else:
                        md_parts.append(f"- {ref}")
            elif key == "evaluation_plan" and isinstance(value, dict):
                header = key.replace("_", " ").title()
                md_parts.append(f"## {header}\n")
                for sub_key, sub_val in value.items():
                    sub_header = sub_key.replace("_", " ").title()
                    if isinstance(sub_val, list):
                        md_parts.append(f"**{sub_header}**: " + ", ".join(str(v) for v in sub_val))
                    else:
                        md_parts.append(f"**{sub_header}**: {sub_val}")
            elif isinstance(value, str):
                header = key.replace("_", " ").title()
                md_parts.append(f"## {header}\n\n{value}")
            elif isinstance(value, dict):
                header = key.replace("_", " ").title()
                md_parts.append(f"## {header}\n")
                for sub_key, sub_val in value.items():
                    sub_header = sub_key.replace("_", " ").title()
                    md_parts.append(f"**{sub_header}**: {sub_val}")
        return "\n\n".join(md_parts)


class ProposalSynthesizer:
    def __init__(self, provider: LLMProvider, ensemble_reviewer=None):
        self._provider = provider
        self._ensemble_reviewer = ensemble_reviewer
        self._prompt_template = (PROMPT_DIR / "synthesis_system.md").read_text()

    async def synthesize(
        self,
        idea: ResearchIdea,
        novelty_report: NoveltyReport | None = None,
        feasibility_report: FeasibilityReport | None = None,
        supporting_papers: list[Paper] | None = None,
        gaps: list | None = None,
    ) -> ResearchProposal:
        """Generate a structured research proposal."""
        literature = self._format_literature(supporting_papers or [])
        key_risks = feasibility_report.key_risks if feasibility_report else []

        gap_descriptions = ""
        if gaps:
            gap_lines = []
            for g in gaps[:8]:
                gap_lines.append(
                    f"- **{g.title}** (confidence: {g.confidence:.2f}, type: {g.gap_type}): "
                    f"{g.description}"
                )
            gap_descriptions = "\n".join(gap_lines)

        closest_matches = ""
        if novelty_report and novelty_report.closest_matches:
            match_lines = []
            for m in novelty_report.closest_matches[:5]:
                title = m.get("title", "Unknown")
                dist = m.get("distance", "N/A")
                abstract = m.get("abstract", "")
                line = f"- **{title}** (distance: {dist})"
                if abstract:
                    line += f"\n  Abstract: {abstract}"
                match_lines.append(line)
            closest_matches = "\n".join(match_lines)

        feasibility_reasoning = ""
        if feasibility_report:
            feasibility_reasoning = (
                f"Overall feasibility: {feasibility_report.overall_score:.1f}/10\n"
                f"Reasoning: {feasibility_report.reasoning}\n"
                f"Sub-scores: data={feasibility_report.data_availability:.1f}, "
                f"compute={feasibility_report.computational_requirements:.1f}, "
                f"methods={feasibility_report.methodological_complexity:.1f}, "
                f"eval={feasibility_report.evaluation_plan:.1f}, "
                f"novelty_grounding={feasibility_report.novelty_grounding:.1f}, "
                f"impact={feasibility_report.impact_potential:.1f}"
            )

        prompt = Template(self._prompt_template).render(
            title=idea.title,
            problem=idea.problem_statement,
            method=idea.proposed_method,
            contributions=idea.expected_contributions,
            evaluation=idea.evaluation_approach,
            novelty_arguments=novelty_report.novelty_arguments
            if novelty_report
            else "Not assessed",
            timeline=feasibility_report.estimated_timeline if feasibility_report else "3-6 months",
            risks="; ".join(key_risks) if key_risks else "Not assessed",
            key_risks=key_risks,
            literature=literature,
            gap_descriptions=gap_descriptions,
            closest_matches=closest_matches,
            feasibility_reasoning=feasibility_reasoning,
        )

        try:
            result = await self._provider.structured_output(
                messages=[
                    {
                        "role": "system",
                        "content": "You are an expert AI/NLP research proposal writer.",
                    },
                    {"role": "user", "content": prompt},
                ],
                schema={
                    "type": "object",
                    "properties": {
                        "title": {"type": "string"},
                        "abstract": {"type": "string"},
                        "introduction": {"type": "string"},
                        "related_work": {"type": "string"},
                        "proposed_method": {"type": "string"},
                        "expected_contributions": {"type": "string"},
                        "evaluation_plan": {
                            "type": "object",
                            "properties": {
                                "datasets": {"type": "array", "items": {"type": "string"}},
                                "baselines": {"type": "array", "items": {"type": "string"}},
                                "metrics": {"type": "array", "items": {"type": "string"}},
                                "ablation_design": {"type": "string"},
                                "summary": {"type": "string"},
                            },
                        },
                        "timeline": {"type": "string"},
                        "references": {
                            "type": "array",
                            "items": {
                                "type": "object",
                                "properties": {
                                    "authors": {"type": "string"},
                                    "year": {"type": "integer"},
                                    "title": {"type": "string"},
                                    "venue": {"type": "string"},
                                    "doi": {"type": "string"},
                                    "url": {"type": "string"},
                                },
                            },
                        },
                        "risk_mitigation": {"type": "string"},
                    },
                    "required": ["title", "abstract", "introduction", "proposed_method"],
                },
                temperature=0.4,
            )
            proposal = ResearchProposal(**result)

            # Quality gate — retry once if sections are too short
            if not self._check_quality(proposal)[0]:
                augmented_prompt = prompt + (
                    "\n\nIMPORTANT: Your previous attempt had sections that were too short. "
                    "Ensure abstract is at least 150 words, introduction at least 100 words, "
                    "and proposed_method at least 100 words."
                )
                try:
                    result2 = await self._provider.structured_output(
                        messages=[
                            {
                                "role": "system",
                                "content": "You are an expert AI/NLP research proposal writer.",
                            },
                            {"role": "user", "content": augmented_prompt},
                        ],
                        schema={
                            "type": "object",
                            "properties": {
                                "title": {"type": "string"},
                                "abstract": {"type": "string"},
                                "introduction": {"type": "string"},
                                "related_work": {"type": "string"},
                                "proposed_method": {"type": "string"},
                                "expected_contributions": {"type": "string"},
                                "evaluation_plan": {
                                    "type": "object",
                                    "properties": {
                                        "datasets": {"type": "array", "items": {"type": "string"}},
                                        "baselines": {"type": "array", "items": {"type": "string"}},
                                        "metrics": {"type": "array", "items": {"type": "string"}},
                                        "ablation_design": {"type": "string"},
                                        "summary": {"type": "string"},
                                    },
                                },
                                "timeline": {"type": "string"},
                                "references": {
                                    "type": "array",
                                    "items": {
                                        "type": "object",
                                        "properties": {
                                            "authors": {"type": "string"},
                                            "year": {"type": "integer"},
                                            "title": {"type": "string"},
                                            "venue": {"type": "string"},
                                            "doi": {"type": "string"},
                                            "url": {"type": "string"},
                                        },
                                    },
                                },
                                "risk_mitigation": {"type": "string"},
                            },
                            "required": ["title", "abstract", "introduction", "proposed_method"],
                        },
                        temperature=0.4,
                    )
                    proposal2 = ResearchProposal(**result2)
                    if self._check_quality(proposal2)[0]:
                        return proposal2
                except Exception:
                    pass

            # Ensemble review (Gap 6)
            if self._ensemble_reviewer:
                try:
                    review_result = await self._ensemble_reviewer.review(proposal, idea)
                    proposal.sections["ensemble_review"] = review_result
                except Exception as e:
                    logger.warning("Ensemble review failed: %s", e)

            return proposal

        except Exception as e:
            logger.error("Proposal synthesis failed: %s", e)
            return ResearchProposal(
                title=idea.title,
                abstract=idea.problem_statement,
                introduction="Synthesis failed. Manual writing required.",
                proposed_method=idea.proposed_method,
            )

    @staticmethod
    def _format_literature(papers: list[Paper]) -> str:
        if not papers:
            return "No specific supporting papers provided."
        lines = []
        for p in papers[:15]:
            authors = ", ".join(a.name for a in p.authors[:3])
            if len(p.authors) > 3:
                authors += " et al."
            line = f"- {authors} ({p.year or 'n.d.'}). {p.title}. {p.venue or 'Unknown venue'}."
            if p.doi:
                line += f" DOI: {p.doi}."
            elif p.url:
                line += f" URL: {p.url}."
            if p.arxiv_id:
                line += f" arXiv: {p.arxiv_id}."
            if p.abstract:
                line += f"\n  Abstract: {p.abstract[:200]}"
            lines.append(line)
        return "\n".join(lines)

    @staticmethod
    def _check_quality(proposal: ResearchProposal) -> tuple[bool, list[str]]:
        """Validate proposal section lengths. Returns (pass, issues)."""
        issues = []
        min_words = {"abstract": 50, "introduction": 100, "proposed_method": 100}
        for section, threshold in min_words.items():
            text = proposal.sections.get(section, "")
            if len(text.split()) < threshold:
                issues.append(f"{section} has fewer than {threshold} words")
        return len(issues) == 0, issues

